insert into public.reference_passages
  (id, source_id, branch, personnel_category, occupation_code, occupation_title, section_type, rank_band, components, heading, chapter, body, body_sha256, pdf_page_start, pdf_page_end, printed_page, sort_order, effective_from, effective_to, cumulative, skill_level)
values
  ('e4ec5478-2db5-5c6f-9040-3e53d29a4169', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70A', 'HEALTH CARE ADMINISTRATION', 'general_duties', null, null, 'Description of duties', 'Medical Service Corps (DA PAM 600-4 chapter)', '70A Health Care Administrators serve in a variety of critical roles throughout the entire spectrum of military health. 70As plan, direct, manage, support, and lead health care organizations; 70As work with Army, Navy, Air Force, and Veterans Affairs personnel while supporting and managing clinical support processes, TRICARE operations, as well as, overseeing other administrative/ logistical support processes in the organization. Health Care Administrators manage the clinical business processes critical to ensuring the viability of a health care organization in both operational and institutional settings. 70As pull together the health care teams required to achieve success, regardless of the setting, saving lives while providing the most efficient, effective, health care with finite resources. 70As command or advise commanders at all levels on health care delivery and the management of health care facilities. They participate at all levels of command in establishing and implementing policies and procedures affecting the U.S. Army Medical Department and the Military Health System.', '98368d730655c5c230693d0db9f27f5123ff070b184c2eda202cbabf327e6242', 8, 8, '8', 0, null, null, false, null),
  ('77944c47-f670-5606-8bd5-70b3efecd94e', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70A', 'HEALTH CARE ADMINISTRATION', 'assignments', null, null, 'Description of positions', 'Medical Service Corps (DA PAM 600-4 chapter)', 'On the operational side, 70As serve as Commanders, Executive Officers, DCAs, advisors to allied forces, etc. On the generating and sustainment side, 70As serve as commanders, Chiefs of Staff, DCAs, Army-Baylor University Graduate Program in Health and Business Administration Director or faculty, Executive Officers, Chiefs of Clinical Operations, clinical support, and managed care divisions. They service as analysts, policy makers, or advisors in all TRICARE regions, MEDCOM, OTSG, DA, and TRICARE Management Activity (TMA). 70As should also seek out broadening assignment opportunities in a Security Forces Assistance Brigade (SFAB). SFAB positions have been deemed critical by the Army senior leadership and provide experience across the Army’s strategic mission.', '9c22819b863b483d81f5868664d687e219620ad6115f5622142a7de070432bc3', 8, 8, '8', 1, null, null, false, null),
  ('5da8f146-d209-50df-af3b-87bec33ce2a6', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70A', 'HEALTH CARE ADMINISTRATION', 'prerequisites', null, null, 'Qualifications', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Must be a graduate of the BOLC, AMEDD CCC or LOGC3 and have a minimum of 3 years of experience in a fixed medical/dental facility or field medical activity. Qualifying degrees include: Commission on the Accreditation of Health Care Management Education accredited master’s degree in health care administration or an Association to Advance Collegiate Schools of Business accredited master''s degree in business administration. Officers who possess other master’s/doctor of philosophy (PhD) degrees in administration, may request evaluation of their master’s degree for validation for award of this AOC. Officers with these degrees may be required to complete selected courses to ensure a common educational base in health care administration. Requests will be forwarded to the 70A Consultant who will review the degree for appropriateness with the Chief, Medical Service Branch, Health Services Division, HRC and Director of the Army-Baylor University Graduate Program in Health and Business Administration.', '31214261d2ca6476471029ba6ac12f570023005073d52796c0d138ef25ae4fea', 8, 9, '8', 2, null, null, false, null),
  ('183e8860-4b6c-5141-8abc-0bf5c39ec873', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70A', 'HEALTH CARE ADMINISTRATION', 'training', null, null, 'Unique education/training opportunities', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Basic Health Care Administration Course, AMEDD Executive Skills Course, Inter–Agency Institute for Federal Health Care Executives post–graduate seminar; fellowships with organizations such as the American Hospital Association, Rand Corporation, Congressional Fellowship, Department of Veteran Affairs (DVA), or Centers for Medicare & Medicaid Services; TWI Program with civilian health care organizations; Army-Baylor University Graduate Program in Health and Business Administration; master’s and doctoral degree programs in health services administration, health care economics, operations research/systems analysis, and business administration. Another strategic training opportunity includes Program Management Acquisition Internships (PMAIP), with opportunities identified in Long Term Health Education and Training (LTHET) MILPER messages.', 'be04980ca5c7397fb6bf622f4524dbacfb439057d1c403b2f0b1b21638bafc26', 9, 9, '9', 3, null, null, false, null),
  ('68977e5f-fc0b-5004-9fd8-9c7d78198ea4', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70A', 'HEALTH CARE ADMINISTRATION', 'skills', null, null, 'Unique skills', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Besides the skill sets outlined in figure 1, 70As are expected to have developed the following skill sets at the following levels:', '3815d030cbd659ff148fa6e0b51e0d6b7f809f714d4dc61cbf128f0e442417c2', 9, 9, '9', 4, null, null, false, null),
  ('705cc77f-d59e-5af1-9f4c-7742c5d73905', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70A', 'HEALTH CARE ADMINISTRATION', 'skills', 'O-3', null, 'Unique skills (CPT)', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Understanding of Joint Commission (TJC) survey standards; budget management at clinic/departmental level; TRICARE policies; Army appointing and business process policies; Army civilian human resource management.', '061c81ef0c7b145dfa289e06fd7ca5e614a0ecf4985fc432a2920cbf97fea918', 9, 9, '9', 5, null, null, false, null),
  ('2d12d051-45e9-58e5-a1fa-313209a1b8ad', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70A', 'HEALTH CARE ADMINISTRATION', 'skills', 'O-4', null, 'Unique skills (MAJ)', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Contract/project management skills; facilities maintenance and environment of care knowledge; health care law and contract law; civilian employee regulations and HR practices; business plan development to include understanding of workload measurement tools and financial reimbursement / budgeting models. Complete initial training and if possible obtain certification in Lean Daily Management, Lean Six Sigma, or Project Management. Develop analytic skills to include data extraction, manipulation, and hypothesis testing. Attend the WISDOM Course and/or Clinical Excellence Training.', '0fed0cdef5a7f269833851811cd27564f910b8b4d07f351e1447983d988d0326', 9, 9, '9', 6, null, null, false, null),
  ('855f0877-6792-5d67-8f27-e89a8a9990f2', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70A', 'HEALTH CARE ADMINISTRATION', 'skills', 'O-5', null, 'Unique skills (LTC)', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Thorough understanding of TRICARE contracts and roles and responsibilities of TRICARE Regional Offices and enhanced Multi-Service Markets; knowledge of DVA/DoD Sharing programs; budget management at the facility level; strategic planning to include common environmental assessment / analysis tools, organizational assessment tools, and robust performance improvement systems like Balanced Scorecard, Lean Six Sigma, data dashboards, and decision support tools.', 'a30624dd3c5dc2cddac50ff7ebf847cc50d8ede0561ab0c4987813e76af9e531', 9, 9, '9', 7, null, null, false, null),
  ('51ebde5f-c118-57f7-9e01-ae2caefb9e96', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70A', 'HEALTH CARE ADMINISTRATION', 'skills', 'O-6', null, 'Unique skills (COL)', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Strategic communications; Medical executive competencies.', 'ec3327a3303115a27d85aaad00ce53cc1670282a8868bb0557e1f197e8a63870', 9, 9, '9', 8, null, null, false, null),
  ('cb2eb354-abbf-5aee-9377-8f09128cce2e', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70B', 'HEALTH SERVICES ADMINISTRATION', 'general_duties', null, null, 'Description of duties', 'Medical Service Corps (DA PAM 600-4 chapter)', 'At the operational level, plans, coordinates, monitors, evaluates, and advises unit commanders and staff in both medical and non–medical areas of patient evacuation, treatment and tracking; preventive medicine, organizational administration, supply, training, operations, transportation, and maintenance. Duties are performed primarily in TOE and occasionally TDA organizations, both CONUS and OCONUS. This is the entry level AOC for MFA 70. MSC accessions come primarily from AOC 70B; all officers entering the MSC in AOC 70B will be reclassified into another specialty prior to promotion to MAJ (see para 3.a.(3) (b)(4) above).', '82091b41f19e2fa37383ecb5d7e6ea1a342a533544e4a3823a392cc7b403cd04', 8, 8, '8', 9, null, null, false, null),
  ('4bda4c81-c5c3-5670-b196-c916249c643c', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70B', 'HEALTH SERVICES ADMINISTRATION', 'assignments', null, null, 'Description of positions', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Positions requiring the AOC include— Medical Platoon Leader, Commander, Medical/Dental Company/Detachment; Hospital Administrative Officer; and most company grade positions in MFA 70.', 'fa65046bfc1b447177be0cdaf7d6b81ac4d88c07221c18f48555840c467dc390', 8, 8, '8', 10, null, null, false, null),
  ('a4d22d4b-483d-5978-8417-59a3b5e3742f', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70B', 'HEALTH SERVICES ADMINISTRATION', 'prerequisites', null, null, 'Qualifications', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Must have at least a baccalaureate degree to meet AMEDD commissioning requirements and successfully completed the AMEDD BOLC.', 'c78ee24f37c5403b67b634522cef89fe6b9b1b327e173a2a30b06f0e435f2e67', 8, 8, '8', 11, null, null, false, null),
  ('4553bf6a-d53a-57b9-97ce-75eb69bdd8a4', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70B', 'HEALTH SERVICES ADMINISTRATION', 'training', null, null, 'Unique education/training opportunities', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Through coordination with HRC Branch, officers in this AOC may attend military schools to attain projected AOCs in the MFA 70. Airborne, Air Assault, and Ranger training may be attended depending on current/projected assignments, available training opportunities, and needs of the Army. It is highly encouraged that officers compete for and obtain the Expert Field Medical Badge (EFMB). EFMB training/testing is conducted at each post and is usually managed at the brigade combat team, division, corps, or installation level. Another strategic training opportunity includes Program Management Acquisition Internships (PMAIP), with opportunities identified in Long Term Health Education and Training (LTHET) MILPER messages.', 'f6acebf8293285cf651aaf2a87889f5fdf5b6b77bb5a122d333cb9eac9206424', 8, 8, '8', 12, null, null, false, null),
  ('e9504fe5-92cc-5eed-a45e-7f57c9dfa642', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70C', 'HEALTH SERVICES COMPTROLLER', 'general_duties', null, null, 'Description of duties', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Serves as the principal adviser to the commander on all aspects of resource management to include financial, budgeting, programming, manpower management, management analysis, expense reporting, commercial activities, agreements, business case analysis (BCA), and internal controls. Makes recommendations that optimally balance the organization’s mission with available resources, while minimizing risk and maximizing return on investment. Maintains proficiency with multiple financial databases, managed care reports and analyses, and systems knowledge in order to generate data-driven recommendations and insights for the commander. Interprets financial laws and Comptroller General decisions. Provides oversight and guidance on agreements, including Memorandum Of Understanding (MOU), Memorandum Of Agreement (MOA), and Intergovernmental/Inter-service Support Agreements (ISSA). Prepares, consolidates, and analyzes financial data and management information systems reports in support of the Planning, Programming, Budgeting, and Execution (PPBE) process. Prepares and distributes reports and financial statements to provide the commander and staff with adequate information on management, status of funds, and budget execution. Develops and implements plans and policies for effective and economical utilization of manpower resources. Manages the Medical Expense Reporting System (MEPRS), the command’s internal control program, review and analysis, and is responsible for organizational strategic planning. Develops policies for, coordinates, and performs all finance and accounting functions. Examines, manages, and certifies military and civilian payrolls, travel, commercial accounts, and other vouchers and claims. Directs disbursement and receipt of both appropriated and non-appropriated funds. Provides administrative assistance in support of payment of legal obligations of the Army or collection of monies due the United States. Plans, develops, and implements changes to financial accounting systems which support the overall Army mission and takes advantage of advances in productivity and efficiency. Trains military and civilian personnel in all areas of resource management. Duties are performed in TOE and TDA organizations both CONUS and OCONUS.', 'deaba8a46b86d2713b86ceecdbc6b98ac5e0259d3d925487b47a793145dce2a1', 9, 10, '9', 13, null, null, false, null),
  ('06b4de1c-d9e6-5bcd-aac2-80bdc801a152', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70C', 'HEALTH SERVICES COMPTROLLER', 'assignments', null, null, 'Description of positions', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Positions requiring this AOC include: Comptroller, MEDDAC/MEDCEN/RHC/TOE; Chief Financial Officer, MEDDAC/MEDCEN/RHC; Chief, Program & Budget Office, MEDCEN/MEDCOM; Chief, Management Division, MEDCOM; Staff Officer, MEDCOM/OTSG/Defense Health Agency (DHA); Program Analyst, MEDCOM/OTSG/DHA; Professor, Army-Baylor Program; Congressional Affairs Coordination Office (CACO); Plans, Analysis, & Evaluation (PA&E); Resource Manager, Multi-Service Market (MSM)/Enhanced Multi-Service Market (eMSM). 70Cs should also seek out broadening assignment opportunities in a Security Forces Assistance Brigade (SFAB).', 'e292b13a687bd3e8113c4837cdd06fb30823b851143a8af6a0e914940a07f827', 10, 10, '10', 14, null, null, false, null),
  ('9bcad228-d110-580b-b8eb-b5fc2b79f310', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70C', 'HEALTH SERVICES COMPTROLLER', 'prerequisites', null, null, 'Qualifications', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Must have successfully completed the AMEDD BOLC, CCC, Department of Defense FM Certification, and the Health Services Comptroller Internship. Health Services Comptroller Internship starts are requested through the LTHET non–degree program, or as follow-on to a 70C, LTHET degree program. To hold resource management positions at the LTC and COL levels, officers should possess a master’s/PhD degree in business. Officers who possess a master’s/PhD degree in other related administrative areas (health services administration, health care administration, or public administration) from an accredited program may request evaluation of their degree. These officers may be required to complete selected courses to ensure a common educational base. Requests will be forwarded through the Health Services Comptroller Consultant to the Chief, Medical Service Branch, HSD, HRC. There is one Skill Identifier (SI) that is individually managed within the 70C population: 8X (Army Medical Department Acquisition Officer). 8x is an SI for officers specializing in Program Management of Contracting.', 'd9637aaac3c8b6632c266555476741ffe7807c46c5ceae493cea22cb70f2078e', 10, 10, '10', 15, null, null, false, null),
  ('c016bbcd-52a0-5e4f-b1a2-9684c332f41c', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70C', 'HEALTH SERVICES COMPTROLLER', 'training', null, null, 'Unique education/training opportunities', 'Medical Service Corps (DA PAM 600-4 chapter)', 'LTHET programs include opportunities for master’s and PhD degrees, TWI Program, the Health Services Comptroller Internship, and other professional/military fellowships. Additional professional development opportunities include Syracuse University comptrollership courses, professional military comptroller courses; resource management courses, the TRICARE Financial Management Education Program (TFMEP), and Certified Defense Financial Management (CDFM) courses and examination preparation. Courses in information management, acquisition, contract administration, negotiation skills, health care administration, and data processing systems management enhance performance in this AOC. Another strategic training opportunity includes Program Management Acquisition Internships (PMAIP), with opportunities identified in Long Term Health Education and Training (LTHET) MILPER messages.', 'cceca1a6750e6220e88ca442887dc465c831a0f08534d8e4945ffe4f899bbbf1', 10, 10, '10', 16, null, null, false, null),
  ('e97ec7a1-e47d-55a6-babc-d2a21c1e3de0', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70C', 'HEALTH SERVICES COMPTROLLER', 'skills', null, null, 'Unique skills', 'Medical Service Corps (DA PAM 600-4 chapter)', '70Cs develop the following skill sets at the following levels:', 'c3939585417cc08f34bb49cb5329a6cbd364e7fd80d86ee085431f0541f50ac3', 10, 10, '10', 17, null, null, false, null),
  ('d04a27f2-6880-5719-9b98-bb5467ce5f0a', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70C', 'HEALTH SERVICES COMPTROLLER', 'skills', 'O-3', null, 'Unique skills (CPT)', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Budgeting, Defense Travel System (DTS), Government Purchase Card (GPC) Program, General Fund Enterprise Business System (GFEBS).', '3b17bb17e7c588c15ff6f8d1a08367334104c36020fdff06dc654f752280e778', 10, 10, '10', 18, null, null, false, null),
  ('2ac5d403-82aa-59ed-859a-2d9f37b22de5', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70C', 'HEALTH SERVICES COMPTROLLER', 'skills', 'O-4', null, 'Unique skills (MAJ)', 'Medical Service Corps (DA PAM 600-4 chapter)', 'MHS financing and budgeting; MHS strategic planning and resourcing, agreements, contracting/acquisitions, PA&E, Review and Analysis, and business plan development to include understanding of workload measurement tools and financial reimbursement / budgeting models. After completion of the Health Services Comptroller Internship, CPTs/MAJs are generally assigned to KD positions as the Chief, Resource Management Division in generating force (MEDDACs) or the S8 in the operation force (Medical Brigades). CPTs/MAJs serve in KD assignments a minimum of 24 months and a maximum of 36 months. KD assignments while a CPT are not required for promotion to MAJ, but are required before being eligible for promotion to LTC. These assignments make an officer competitive for future health care executive and enterprise opportunities. The following in table 1 are the KD assignments for CPTs/MAJs: (Tables 1 and 2 To be added)', '8642add144b5525d0b468657e38c7984a84e93639634619d9f21ef8739677f18', 10, 10, '10', 19, null, null, false, null),
  ('66bec7b8-bd24-5c8d-9e5d-034ef884739a', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70C', 'HEALTH SERVICES COMPTROLLER', 'skills', 'O-5', null, 'Unique skills (LTC)', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Commercial sector health care financing; commercial sector best business practices in business and health care administration; health plan management and operations.
(a) The only KD assignment for a LTC is a CSL position. These are generally O-5 level commands. KD assignments are generally 24-36 months. KD assignments while a LTC are not required for promotion to COL. These assignments make an officer competitive for future health care executive and enterprise opportunities.
i. Former O-5 commanders are managed and assigned to specific jobs based on the needs of the Army. ii. Broadening assignments. All other assignments that are not a centrally selected command billet or key billet are considered to be broadening. Experience gained as a LTC provides the Army with officers who have mastery of tactical and operational levels and are adapting to strategic levels. iii. The following in Table 3 are examples of broadening assignments for LTCs: (To be added)', 'f5e4a6c2714644328c62936e21fdecfa50ad4d9f97a696e1ed9e044be788bc13', 10, 11, '10', 20, null, null, false, null),
  ('5f535978-add0-595d-a354-65923e00a49c', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70C', 'HEALTH SERVICES COMPTROLLER', 'skills', 'O-6', null, 'Unique skills (COL)', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Commercial sector health care financing; commercial sector best business practices in business and health care administration; health plan management and operations. The only KD assignment is selection for a CSL command or a nominative key billet. Officers serve in the same four CSL command categories as LTCs; garrison command tour lengths are 24 months but can be extended to 36 months. Former O-6 commanders are managed and assigned to specific jobs based on the needs of the Army.', 'ce6428fea182f34e2cf955bfefe9c037b30904b5796afb141ff63de8a801e1cf', 11, 11, '11', 21, null, null, false, null),
  ('3dff5bac-62cf-5e8f-8979-49dcc9591e08', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70D', 'HEALTH SERVICES SYSTEMS MANAGEMENT', 'general_duties', null, null, 'Description of duties (the chapter titles this AOC "Health Information Technology")', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Advises and assists the medical commander or staff surgeon in the area of health care information management and cyber security. Develops strategy, policy, and plans for the development, implementation, operation, and evaluation of clinical/patient oriented information systems and the administration of support for medical information systems. Develop and participate in governance, budgeting, and life cycle management of health information technology systems, applications, and end user devices. Integrates telecommunications, cyber security, information system administration, administrative services (including functions such as mail, records keeping and official distribution), network engineering, visual information and printing equipment in support of hospital and operational medicine environments. Provides consultative services and detailed technical analysis on planning, developing, implementing, operating, maintaining, securing, and disposing of information systems and networks at medical activities both TDA and TOE. Provides medical communication planning and management for Combat Casualty Care situations. Enable TDA and TOE commanders with Virtual Health capability.', 'fa2574ae303ea454a369689588c143cb1080efa4bd1ab5ed427fe2ea3cd7d7fc', 11, 11, '11', 22, null, null, false, null),
  ('a39c32a1-fa1b-5986-aa7f-14d559544627', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70D', 'HEALTH SERVICES SYSTEMS MANAGEMENT', 'assignments', null, null, 'Description of positions', 'Medical Service Corps (DA PAM 600-4 chapter)', '1. TOE. Operational positions at the company and field grade ranks as the S-6, G-6, J-6, Health Information Systems Officer, and Health Informatics Officer. Officers are also highly competitive for Battalion Executive and Operations Officer positions in medical brigades, medical battalions, and troop commands. 70Ds should also seek out broadening assignment opportunities in a Security Forces Assistance Brigade (SFAB).
2. TDA. Strategic positions in this AOC include Health Care Information Management Officer; Chief, Technology Officer; Information Systems Analysis; Chief, Information Management Officer, OTSG G-6; Deputy/ACS/M; Assistant Chief of Staff for Information Management; Health Informatics Officer; Information Management/ Information Technology (IM/IT) Planner for Health Facilities Planning Agency; Information Management Officer; Information Management Staff Officer; Program or Project Management Officer in the Defense Health Agency or Program Executive Office.', '954211d5320d247332c43ab56f46eb5d4ec53afa5db104d69625446a39167102', 11, 11, '11', 23, null, null, false, null),
  ('e54edf02-3fea-59d0-af43-f5dab14a14a5', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70D', 'HEALTH SERVICES SYSTEMS MANAGEMENT', 'prerequisites', null, null, 'Qualifications', 'Medical Service Corps (DA PAM 600-4 chapter)', 'All 70Ds officers must be a graduate of the Medical Information Management Course and receive this designation as their primary AOC as determined by the AOC Designation Panel around six to eight years of commissioned service as 70B. There are two Skill Identifiers (SI) that are individually managed within the 70D population, 9B (Board Certification) and 8X (Army Medical Department Acquisition Officer). 9B is an SI for officers who earn one of the following board certifications: College of Healthcare Information Management Executives (CHIME) Certified Healthcare Chief Information Officer (CHCIO) or the Certified Professional in Healthcare Information and Management Systems (CPHIMS). 8X is an SI for AMEDD officers in the Army Acquisition Workforce specializing in Information Technology or Program Management.', 'c2e3560ec03ff6fc7658cc4657c30a1d04d8d6d3c24bb7eaff41eaa765ff5100', 11, 11, '11', 24, null, null, false, null),
  ('ac8faaae-15f1-59ad-834b-715d71899735', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70D', 'HEALTH SERVICES SYSTEMS MANAGEMENT', 'training', null, null, 'Unique education/training opportunities', 'Medical Service Corps (DA PAM 600-4 chapter)', '1. TOE. Operational training opportunities include the Medical Information Management Course; and Information Systems Engineer (ISE) Course (FA26B); Brigade and Battalion S6 Staff Course; access to short courses at installation Signal Universities to include SharePoint and CompTIA certifications in A+, Net+, Sec+, and Advanced Security Practitioner Certification; and the Joint Medical Operations Course; Medical Communications for Combat Casualty Care System Administration Course; Joint Medical Planning Tool Course; Small Group Instructor Training Course; Project Management Course; Healthcare Administration and Management Course; Patient Administration Course.
2. TDA. Strategic training opportunities include earning the Federal Chief Information Officer Certificate through the National Defense University; funded 70D civilian graduate level degree programs (master’s and doctoral) to include the U.S. Army–Baylor University Program in Health and Business Administration; TWI Program opportunities at various locations such as Baptist Health System; Program Management Acquisition Internships (PMAIP) and information technology (IT) Acquisition Level I-III certifications; project management training; a master’s degree in Information Management, Information Technology, Cyber Security, Technology Management, and Health Care Administration; Doctoral degrees in Information Management, Information Technology, Technology Management, and Operations Research/Systems Analysis.
3. Both. Members of the 70D AOC will have opportunities to work in and become subject matter experts in the domains of; Information Resource Management; Cyber Security; Mobility-Virtual Health; and IM/IT Acquisitions. Another strategic training opportunity includes Program Management Acquisition Internships (PMAIP), with opportunities identified in Long Term Health Education and Training (LTHET) MILPER messages.', '422fa1cf9559bff7c0e85c3e053ed5d63791b812cec797bec168ba24ef186879', 12, 12, '12', 25, null, null, false, null),
  ('7fd03f59-c516-55bb-a5b4-5dde456691b2', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70E', 'PATIENT ADMINISTRATION', 'general_duties', null, null, 'Description of duties', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Advises commanders and staff in all aspects of patient administration. Plans, organizes, directs, and controls patient administration in a variety of health care agencies, including command headquarters at the DoD, JCS and Health Affairs levels, health services facility, clinical support division, department, service, or branch of a military medical/dental facility. Collects and analyzes patient and institutional data. Assists medical staff in evaluating quality of patient care and in developing criteria and methods for such an evaluation. Advises the medical commander on issues pertaining to patient accountability, disability evaluation processing, health information management, privacy, medical coding, eligibility for care, decedent affairs, and patient movement. Further serves as an advisor on matters pertaining to the standards prescribed by the Joint Commission. Duties are performed in TOE/TDA organizations, both CONUS and OCONUS.', 'd2bbff0bf6d3aeaa067473351106cfd4f187d2c6ed78cb34420291bcb8ba69ba', 14, 14, '14', 26, null, null, false, null),
  ('a7997a87-f293-53e4-be32-52495d075d50', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70E', 'PATIENT ADMINISTRATION', 'assignments', null, null, 'Description of positions', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Positions requiring this AOC include: Chief, Patient Administration Division MEDDAC/MEDCEN, Medical Brigades, Combat Support Hospitals, and Multi-functional Medical Battalions; Director or Instructor Medical Center of Excellence; consultant or staff officer, OTSG; Director or staff officer, Patient Administration Systems and Biostatistics Activity; Patient Movement /Operations Officer at the following levels: Theater and Joint Patient Movement Requirements Centers. 70Es should also seek out broadening assignment opportunities in a Security Forces Assistance Brigade (SFAB).', 'e07d66e886bc837a0a5a1bc8459d52a07c667848f007405d7ae48c76d4160ca5', 14, 14, '14', 27, null, null, false, null),
  ('d2289e61-74bd-5d24-8a96-04431b0df818', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70E', 'PATIENT ADMINISTRATION', 'prerequisites', null, null, 'Qualifications', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Must have successfully completed the AMEDD BOLC and CCC. Must have successfully completed the AMEDD Patient Administration Course and completed a one year internship as the Chief, PAD or deputy Chief, PAD at an MTF. To hold positions in this AOC at the LTC and COL levels, should possess a master’s/PhD degree in a directly related discipline from an accredited program acceptable to TSG. Qualifying degrees include: master’s degree in Health Information Management, Health Care Administration or Business. Officers who possess other master’s/PhD degrees (such as those outline in paragraph (e) below) may request evaluation of their master’s degree for validation for award of this AOC following completion of the Patient Administration course and the one year internship. Requests will be forwarded through the Patient Administration Consultant to the Chief, Medical Service Branch, HSD, HRC.', '19a6aaeb4f50c4bfe31ad80f8f91c8c310c512ea45aa5cd0215e1e67a60cb8c1', 14, 15, '14', 28, null, null, false, null),
  ('d39d7980-c0e9-56ab-8b0c-83a5c2176bf0', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70E', 'PATIENT ADMINISTRATION', 'training', null, null, 'Unique education/training opportunities', 'Medical Service Corps (DA PAM 600-4 chapter)', 'The University of Pittsburgh Program in Health Information Systems and The U.S. Army–Baylor University Program in Health and Business Administration are recommended for officers in this AOC. A program in Health Information Management (HIM) prepares professionals responsible for the development and management of health information systems consistent with the clinical, fiscal, administrative, ethical, and legal requirements of health care institutions. Graduates of an HIM program are expected to analyze, design, implement, and evaluate health information systems. As members of the health care team, they interact with other health care professionals and administrators, and provide health care data for patient care, research, quality improvement, strategic planning, reimbursement, and related managerial functions. A 70E officer should also consider programs that offer specialized courses of study for students who are seeking eligibility to sit for the credentialing examination to become a Registered Health Information Administrator. Other master’s degree programs appropriate for officers within this AOC are health services administration, medical informatics, health services management, business administration, business management, financial management, biostatistics, public health, and homeland security/medical emergency preparedness. Recommended courses include Medical Management of Chemical Casualties Course, Contracting Officer Representative Course, Health Care Administrators Course (short course), Operations Research/Systems Analysis, Civilian Personnel Management, Medical Information Management Officer Course, Project Management Course, Functional Proponent Course, and the NATO Joint Medical Planners Course. Fellowships and TWI Program opportunities are also recommended for patient administration officers but vary in availability. Another strategic training opportunity includes Program Management Acquisition Internships (PMAIP), with opportunities identified in Long Term Health Education and Training (LTHET) MILPER messages.', 'fa82f18af3fde63db7e9893286bf0168211da1489b341b224f255acf63f21861', 15, 15, '15', 29, null, null, false, null),
  ('0ce10cee-93c0-53d2-b1ba-500f23ad4a9f', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70E', 'PATIENT ADMINISTRATION', 'skills', null, null, 'Unique skills', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Besides the skill sets outlined in figure 1, 70Es are expected to have developed the following skill sets at the following levels:', '38c81f1524784945575ee00436e1f978957547fce046612df4af45a399eb1ab3', 15, 15, '15', 30, null, null, false, null),
  ('a2092bb1-8938-58c7-bc6d-c290956436e7', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70E', 'PATIENT ADMINISTRATION', 'skills', 'O-3', null, 'Unique skills (CPT)', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Understanding of the Joint Commission survey standards; understanding of HIPAA; functional knowledge of patient movement systems and processes; MTF revenue cycle; civilian employee regulations and HR practices.', '675ac084381f69b7f8798a78d5974c51a8d6851165d0632918c2adf0fc7d318e', 15, 15, '15', 31, null, null, false, null),
  ('7174d053-1e29-503a-b468-84f169c12da8', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70E', 'PATIENT ADMINISTRATION', 'skills', 'O-4', null, 'Unique skills (MAJ)', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Contract/project management skills; business plan development to include understanding of workload measurement tools and financial reimbursement/budgeting models, knowledge of project/program management. Knowledge of Army, Joint, and federal health care information (clinical and administrative) architecture and how it relates to the Global Information Infrastructure, theater, Army, Joint and federal health care environments; understanding of the Health Incident Command System. Professional certifications.', 'da07bc09ca2178e1e2330475be523a78c5b03762ed88ac3ef8a4810cb5a20d89', 15, 15, '15', 32, null, null, false, null),
  ('3015f030-641a-53ae-a309-ebecf1195e77', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70E', 'PATIENT ADMINISTRATION', 'skills', 'O-5', null, 'Unique skills (LTC)', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Roles and responsibilities of TROs/eMSMs; knowledge of DVA/DoD Sharing programs; strategic planning to include common environmental assessment / analysis tools, organizational assessment tools, and management systems like BSC, LSS, dashboards, and decision support center tools. PPBE/POM execution, Joint integration of medical systems, 9A Proficiency designation should be pursued.', 'fe91a54938598999209c5b9d5c97b3b4b427a3f9c0c64b82d07e63a80b7c6dc7', 15, 15, '15', 33, null, null, false, null),
  ('3df30eef-499a-5ac0-be9c-9d92612a1b76', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70F', 'HEALTH SERVICES HUMAN RESOURCES', 'general_duties', null, null, 'Description of duties', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Advises commanders and staff in all aspects of health services human resources management to include shaping the force and matters/policies pertaining to all assigned military personnel, DoD civilian personnel, and contractors. Plans, develops, and directs administrative management activities and services in medical organizations which include: distribution, publications, correspondence, records and files management, and desktop publishing. Plans, develops, and directs human resource systems that support and implement programs concerning the components of the human resources management life cycle. Included are strength management, accessions, personnel operations, personnel requisitioning, awards, promotions and reductions, classifications and reclassifications, assignments, finance and special pays, evaluations reports, reenlistments, eliminations, and separations. Manages the activities of personnel operational elements providing support to organizations, headquarters, and individuals. Trains military and civilian personnel in personnel services support and organizational administration. Plans and develops human resource best practices in support of the re– engineering of business practices. Duties are performed in TOE/TDA organizations, both CONUS and OCONUS, at the tactical, operational, and strategic levels.', '89332772cbae32e0a6cc0e98aa5f0a6178a1659e5393ba783c73eac1ab4ae647', 15, 16, '15', 34, null, null, false, null),
  ('af7f7951-55b7-5748-b9ba-f10600b6b1a1', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70F', 'HEALTH SERVICES HUMAN RESOURCES', 'assignments', null, null, 'Description of positions', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Positions requiring this AOC include: Adjutant; BN/MSC S-1; RHC G-1; Secretary General Staff; RHC/MSC; Chief, Personnel HR Division; Health Services HR Officer; AMEDD Health Care Recruiter; HRC Assignment Officer; Commander; AMEDD Personnel Proponency Directorate (APPD); Professional Education and Training Department (PETD); Directorate of Military Personnel Management (DMPM); AMEDD Personnel System Staff Officer (APERSSO) (AGR); Director of HR, OTSG. 70Fs should also seek out broadening assignment opportunities in a Security Forces Assistance Brigade (SFAB).', '3c90fa505584f03be60b3f8a37a8bce07c9fe605dc9f53147a359c32456b4d93', 16, 16, '16', 35, null, null, false, null),
  ('6aedca00-18ce-5d0c-ac77-f07571070dd5', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70F', 'HEALTH SERVICES HUMAN RESOURCES', 'prerequisites', null, null, 'Qualifications', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Must have successfully completed the AMEDD Human Resources Manager Course. To hold positions in this AOC at the LTC and COL levels, 70Fs should possess a master’s degree in an HR-related discipline from an accredited program.', '8302150a31d104aa6ae256f0a8210d6ca1599ebe424ad41af51910dd2ad6b424', 16, 16, '16', 36, null, null, false, null),
  ('27ab34f7-d7d8-5fc6-a1f5-01c5aea75197', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70F', 'HEALTH SERVICES HUMAN RESOURCES', 'training', null, null, 'Unique education/training opportunities', 'Medical Service Corps (DA PAM 600-4 chapter)', 'A 70F officer may attend the Human Resources “Track” during attendance at the AMEDD CCC. The AMEDD Human Resources Manager Course at the MEDCoE provides invaluable training for the human resources officer. In addition, officers in this AOC will gain tremendous insight by working as an AMEDD Health Care Recruiter. Recommended master’s degree programs include majors in human resources management, human resources development, business administration and management, public administration, industrial administration, labor relations, international business, organizational behavior and development, management of information systems, marketing, education, health care administration, and operational research and systems analysis. Officers within this AOC may apply for LTHET in a human resources discipline. They may also apply for an opportunity to serve as an intern at the OTSG, MTF, or the AMEDD Personnel Proponency Directorate (APPD), or for an opportunity to take part in a TWI Program experience. Officers are encouraged to attend the annual HR Symposium. Another strategic training opportunity includes Program Management Acquisition Internships (PMAIP), with opportunities identified in Long Term Health Education and Training (LTHET) MILPER messages.', '610f71aaf23c6dd6f0543c49a835d18b42e287167fb12459879b385c8c564654', 16, 16, '16', 37, null, null, false, null),
  ('596a0d97-8b2f-59fd-9084-80af189687a9', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70H', 'HEALTH SERVICES PLANS, OPERATIONS, INTELLIGENCE, SECURITY AND TRAINING', 'general_duties', null, null, 'Description of duties', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Serves as the principal advisor to commanders at all levels in the areas of field medical operations. Directs and coordinates staff functions pertaining to health services plans, operations, intelligence, security, and training. Duties are performed in TOE/TDA organizations, both CONUS and OCONUS.', '77887962620e50cbc1b2c0afba5b06dfcdde73f1c4969b9674dbbbd24413ac20', 16, 16, '16', 38, null, null, false, null),
  ('0cdcbf4a-5a67-53c7-bca0-1ef2c329035b', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70H', 'HEALTH SERVICES PLANS, OPERATIONS, INTELLIGENCE, SECURITY AND TRAINING', 'assignments', null, null, 'Description of positions', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Positions requiring this AOC include: Medical Plans, Operations, Intelligence, Security, and Training Officer; Plans, Intelligence and Operations Officer; Assistant Chief of Staff (ACoS), Plans and Training Officer; Intelligence Officer; Instructor; ACoS, Plans, Intelligence, and Operations, MEDCOM/ Brigade; Health Services Plans, Intelligence, Security, and Training Operations Research Analyst; Battalion S-3; Medical Operations Officer, BDE Surgeon Cell (UA); Special Forces Group; Medical Operations Officer; Observer / Controller; Instructor MEDCoE / LOGC3; Plans and Training Officer MEDCoE; Battalion Executive Officer; Support Operations Officer; Force Health Protection Officer (FHP); Brigade S-3; Medical Planner, UA, COCOM, DRU, ACOM, ASCC; Plans and Training Officer, Regional Health Command; Medical Operations Officer, USA Special Operations Command (USASOC); Staff Officer, Department of the Army, Department of Defense, Joint, OTSG, MEDCoE; Medical Planner, NORTHCOM, Joint Task Force National Capital Region, USASOC, Special Operations Command; Chief of Staff, Medical Brigade; Joint Regional Medical Planner, NORTHCOM; Deputy Surgeon, UA, Combatant and Major Commands. 70Hs should also seek out broadening assignment opportunities in a Security Forces Assistance Brigade (SFAB).', '2f0db49e98de5343c83fd27bdd8fb4e1e43f31088b90c793113c37da43915e67', 16, 16, '16', 39, null, null, false, null),
  ('80e9edbf-8163-532a-b38e-0c501d4651f1', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70H', 'HEALTH SERVICES PLANS, OPERATIONS, INTELLIGENCE, SECURITY AND TRAINING', 'prerequisites', null, null, 'Qualifications', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Must have successfully completed the AMEDD CCC or LOGC3 to hold positions through MAJ; must be an ILE graduate to hold positions through COL; and should possess a master’s degree from an accredited program acceptable to TSG in a field related to the management of health services.', 'c16dbe4fced9b86826b846aeee52579074b3db02a457aca820158631dfd99394', 16, 16, '16', 40, null, null, false, null),
  ('992192f3-b1f2-5bdb-8975-1a0e1db6208f', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70H', 'HEALTH SERVICES PLANS, OPERATIONS, INTELLIGENCE, SECURITY AND TRAINING', 'training', null, null, 'Unique education/training opportunities', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Courses to obtain skills in Strategic Intelligence, Operations Research/Systems Analysis, and Training Development are some of the opportunities available to officers in this AOC. Short courses include the Health Services Plans, Operations, Intelligence Security and Training Course (70H Course), Tactical Combat Casualty Care Course, Medical Strategic Leadership Program. 70Hs assigned to USASOC can attend the Special Operations Medical Indoctrination Course, the Joint Special Operations Medical Orientation. 70Hs assigned to or seeking Joint experience should attend the Joint Medical Operations Course, the NATO Joint Medical Planners Course, and the Joint Medical Planning Tool Course. Courses to obtain skills in Strategic Intelligence, Operations Research/Systems Analysis, and Training Development are some of the opportunities available to officers in this AOC. Broadening assignment opportunities include the RAND Fellowship, Red Cross Fellowship, and Congressional Fellowship. Master’s degree programs recommended for officers within this MFA should include the following courses: Operations Research; Operations Management; Health Care Education Administration; Health Care Planning; Health Care Policy and Management; Health Care Information Systems; Health Care Technology; Health Systems Management; Health Care Management; Health Policy and Management; Master’s degree in Public Health with related concentration; International Policy and Management; International Health Development; International Humanitarian Assistance; International Health Organization and Management; Government and International Public Administration; International Health Planning and Development; History, Science and Technology; History of Military Medicine; History of Health Sciences; Strategic Intelligence; International Strategy and Intelligence; Homeland Security; Government with Homeland Security Concentration; National Security; Emergency Management; Emergency Management Concentration; Emergency and Disaster Preparedness; and Health Management and Policy. Another strategic training opportunity includes Program Management Acquisition Internships (PMAIP), with opportunities identified in Long Term Health Education and Training (LTHET) MILPER messages.', '0dd12aec5a1efb794e0ef6b61457b0012454485bb6554be5e9965bbae54c51e7', 17, 17, '17', 41, null, null, false, null),
  ('7ca452f6-345e-5e56-8701-55cae6ba8615', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70K', 'HEALTH SERVICES MATERIEL', 'general_duties', null, null, 'Description of duties', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Health Services Materiel Officers (HSMO) command medical units and serve as Logistics staff officers. HSMOs serve as the tactical, operational, and strategic levels and require extensive knowledge and experience in planning, preparing, executing, and assessing all warfighting functions while maintaining an AOC in the sustainment warfighting function subcomponents, health service support and logistics (see ADP 4–0 Sustainment for discussions on the sustainment warfighting functions). Health service support tasks include casualty care, medical evacuation and medical logistics. Medical logistics tasks include, but are not limited to acquisition, Class VIII medical supply and maintenance, blood storage and distribution, optical fabrication and production, property management, and medical facilities management. Logistics tasks include, supply, field services, transportation, maintenance, distribution, operational contract support, and general engineering. HSMOs must be competent in these tasks across all warfighting functions in support of both conventional force and SOF. HSMOs must be adaptive and trained to support any force by nontraditional means across dispersed logistically undeveloped non-permissive areas for enduring operations. HSMOs serve across the functional, health care executive, and enterprise talent management lanes. HSMOs are interwoven into clinical support and supply chain management system. HSMOs are competitive for functional and AMEDD immaterial command and key billets. Select HSMOs have the opportunity to compete for FA90 and Acquisition (Contracting and Product Management) CSL positions. The Health Facilities Planner specialty is included in this AOC. A Health Facilities Planner may be responsible for planning, programming, design management, design review, and construction management of health care facilities. HMSOs develop their expertise through the four logistical learning areas of supply chain management, health industry management, life-cycle management, and logistical/facilities planning.', 'b989381859217b0db81a17b72dc56c3179e082715db903df741f656a7201b8c4', 17, 17, '17', 42, null, null, false, null),
  ('9ea6b5c4-23f8-5fce-8f8e-6f2791c59809', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70K', 'HEALTH SERVICES MATERIEL', 'assignments', null, null, 'Description of positions', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Positions requiring this AOC include: Chief, Logistics; Deputy Chief of Staff/ACS, Logistics; Commander, Medical Logistics Battalion; S–4; Contracting Officer; Stock Control Officer; Clinical Engineer; Medical Logistics Programmer, OTSG / Assistant Secretary of the Army for Acquisition, Logistics and Technology; Medical Logistics Staff Officer; Division Medical Supply Officer; Property Book Officer; Logistics Systems Officer; Medical Logistics Plans/Operations Officer; Medical Logistics Staff Officer; Hospital Materiel Officer; Health Facility Planning Officer; Commander, Health Facility Planning Agency; Chief, Facilities Division; Chief, Design and Development; Chief, Program and Analysis; Chief, Project Management; Architect; Health Facility Project Officer; Deputy Chief of Staff, Facilities; Executive Officer, Health Facility Planning Agency; and Senior Health Facility Planning Officer, Planning and Portfolio Management Division, Assistant Secretary of Defense for Health Affairs. 70Ks should also seek out broadening assignment opportunities in a Security Forces Assistance Brigade (SFAB).', '33946d6fc1f14e5f74ab1431e9c68697103ff675b93d8ab6f1269d0f2784c394', 17, 18, '17', 43, null, null, false, null),
  ('1f7778bd-b348-540e-a2e4-30b69e40fb9e', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70K', 'HEALTH SERVICES MATERIEL', 'prerequisites', null, null, 'Qualifications', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Health Services Materiel Officer (70K) is the primary AOC for the HSMO. All officers must be a graduate of the Medical Logistics Officer Course and receive this designation as their primary AOC as determined by the AOC Designation Panel around six years of commissioned service as 70B. 70Ks are also eligible to obtain FA90 as a secondary AOC. There are two Skill Identifiers (SI) that are individually managed within the 70K population, 9I (Health Facilities Planner) and 8X (Army Medical Department Acquisition Officer).
1. 9I is the SI designation for officers specializing in facilities management, design, planning and engineering. Facility planners (70K9Is) provide the AMEDD with health care facility planning, programming, and acquisition capabilities. Health facility planning and acquisition encompasses new construction, initial outfitting and transition, sustainment of existing facilities and modernization of aging infrastructure. Operational assignments include Brigade Engineer and Facilities Staff Officer. Officers must possess an undergraduate or graduate degree in architecture, engineering, construction management (A/E/CM) or closely related field, complete the Health Services Materiel Course and a two year utilization tour to be eligible for award of the SI. Officers without undergraduate or graduate degree in architecture, engineering, construction management or closely related field may be awarded the SI after completion of five years cumulative experience serving in 70K9I positions. On a case by case basis, officers without technical or professional degrees in A/E/CM or closely related field may receive partial constructive credit towards the fifth year cumulative experience by achieving professional certifications associated to health facility planning. Award of the 9I SI designation is approved by the 70K9I consultant after a thorough review of the officer''s academic and experiential qualifications.
2. 8X is an SI for officers specializing in Program Management or Contracting.', '44431cb40663e6cf0968d2a2e2dd7f2be506c2e15b75c3e80f6b998ca4741d1b', 18, 18, '18', 44, null, null, false, null),
  ('7e55f226-03fe-5982-af8e-9ac4532aa950', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '70K', 'HEALTH SERVICES MATERIEL', 'training', null, null, 'Unique education/training opportunities', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Strategic training opportunities include the Program Management Acquisition Internship Program (PMAIP), with opportunities identified in Long Term Health Education and Training (LTHET) MILPER messages.
1. Multifunctional Logistics (AOC 90A) MSC officers are offered the chance to hold FA90 KD positions at the CPT and MAJ level, the more common positions being 90A company commands and later as a MAJ in the Support Operations Officer and Executive Officer positions. Ideally, MSC officers will attend LOGC3 in order to obtain the requisite training for them to be successful at those jobs. The Support Operations Course is an acceptable training substitute if an officer did not have the opportunity to attend LOGC3 as a CPT. This applies to both the AC and RC service components. It is this combination of training in conjunction with CPT or MAJ level KD experiences that allow MSC officers to be competitive for command of multifunctional logistics battalions and brigades. Those officers who do not have the requisite training and KD experiences at either the CPT or MAJ level will not be allowed to compete in those LTC/COL command categories. MSC officers that serve in 90A positions and meet the requirements to compete for LTC/COL commands will retain their primary 67 AOCs and the 90A will become a secondary (and/or tertiary) AOC. Active Component officers may branch transfer into the Logistics branch at the rank of CPT if they have less than nine years of AFCS. Transfer authorizations are based on the needs of the Army and may not be available year-to-year. See Smartbook DA PAM 600-3 for further details.
(d) Skill Identifiers (SI) and Coded Positions for Logistics Officers. The below listing includes additional SIs that are critical and available to all AOC 70K logisticians. The SI appears on the officer’s ORB upon completion of training or specific utilization assignments. Officers may serve in coded positions if they hold the identifier or are scheduled for training.
1. Advanced Military Studies Program (AMSP) (6S).
2. Air Assault (2B).
3. Capabilities Development (7Y).
4. Force Management (3R)
5. Green Belt in Lean Six Sigma (LSS) (1X), Black Belt LSS (1Y).
6. Instructor (5K).
7. Joint Planner (3H) for MAJ and above.
8. Parachutist (5P); Jumpmaster (5W)
9. Operational Contract Support (3C).
10. Project Management Professional (PMP) (W5)
11. Special Operations Experience (S-1).
(e) Special Operations Experience. All HSMOs willing to attend Airborne School can serve in SOF formations. Opportunities are available for LTs through LTCs to serve in 70K positions within various SOF formations. HSMOs gain SOF experience as they move between SOF and conventional force assignments performing KD and broadening assignments throughout. These logisticians must be managed with reassignments to SOF to provide continuity of experience that enables a solid foundation for success at the LTC level positions within SOF. SOF assignments are best filled with HSMOs who have previously served successful tours in SOF and these assignments should be managed accordingly when the available assignment pool allows. This TM will provide SOF commanders with the best continuity of support by medical logisticians who have progressively invested and built on their SOF experience.', '2ad2e2dadddf8e67904c8f0657c04078195ac08a634f71cbe35119df503b5df6', 18, 19, '18', 45, null, null, false, null),
  ('e6b8fdb5-db9c-5cf0-a110-f2a60a09e307', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '71A', 'MICROBIOLOGY', 'general_duties', null, null, 'Description of duties', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Serves as a Microbiologist and/or Section, Branch, Department, or Division Chief responsible for the planning, resourcing, execution and/or acquisition of clinical laboratory testing or medical research and development consistent with unit mission. Supervises testing, provides consultation and expert advice, conducts/directs research, and manages laboratory operations including fiscal and personnel resources.', '32cab288ea3a59fa088a6e51098dd165c2f296dedeac627e69075cba92c938e0', 33, 33, '33', 46, null, null, false, null),
  ('bf504d8c-1146-54a5-96b9-915fa4288500', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '71A', 'MICROBIOLOGY', 'assignments', null, null, 'Description of positions', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Positions designated with this AOC include Section, Branch, Department, and Division Chiefs at clinical and medical research laboratories where the specialty of microbiology, virology, bacteriology, parasitology, immunology or molecular biology is required. Officers should also seek out broadening assignment opportunities in a Security Forces Assistance Brigade (SFAB).', '30b84ccbead017a20f5245cfdf138d996a50a4e512475f929008a1cc7f2ae245', 33, 33, '33', 47, null, null, false, null),
  ('fd96187e-27d6-58ea-b204-4c326db2225e', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '71A', 'MICROBIOLOGY', 'prerequisites', null, null, 'Qualifications', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Minimum of master’s degree with specialization in microbiology, virology, bacteriology, parasitology, immunology, or molecular biology from an accredited program acceptable to TSG.
4. Licensure/certification requirements. For clinical / diagnostic positions, the American Board of Medical Microbiology (ABMM), the American Board of Bioanalysis (ABB), the Board of the National Registry of Microbiologists or American Society of Clinical Pathology are highly recommended, but not required. ABMM or ABB certification is required of Directors of Clinical Laboratories. Acquisition Workforce certification is a requirement of product development/research positions coded with the 8X Skill Identifier. Additional certifications include Clinical Pharmacology (Applied Pharmacology), Regulatory Affairs and Project Management Professional.', 'e83b03c6fb939e22aadaec24d6ed95e52633c148c88ee7451991914b6e74e0cd', 33, 34, '33', 48, null, null, false, null),
  ('f0fec4a0-a231-55e7-ab28-173c9259954d', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '71A', 'MICROBIOLOGY', 'training', null, null, 'Unique education/training opportunities', 'Medical Service Corps (DA PAM 600-4 chapter)', 'The PhD programs in microbiology; Annual Medical Laboratory Sciences (Tri–Services) Short Course; clinical microbiology internship; fellowship with the U.S. Food and Drug administration; continuing medical education conferences from associations such as the American Society for Microbiology, American Society of Tropical Medicine and Hygiene and Infectious Diseases Society of America. Another strategic training opportunity includes Program Management Acquisition Internships (PMAIP), with opportunities identified in Long Term Health Education and Training (LTHET) MILPER messages.', 'aa9991731e490bc8610e98d02a6ba1cc676c9bddefbc570f8b94afaf7a585173', 34, 34, '34', 49, null, null, false, null),
  ('02b53fe4-390b-5965-a799-9813870c6db3', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '71B', 'BIOCHEMISTRY', 'general_duties', null, null, 'Description of duties', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Serves as Section, Branch, Division, or Department Chief or Director responsible for the planning and execution of clinical laboratory testing, sample testing for drugs of abuse, or medical research and development consistent with unit mission. Supervises testing, provides consultation and expert advice, conducts/directs research, and manages laboratory operations including fiscal and personnel resources.', '18095ee6cec5e1c044760a6b031a3d23dc1eb4742879559408b3f429184b5d94', 34, 34, '34', 50, null, null, false, null),
  ('32531732-2b87-5661-bacc-91a4482e7be5', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '71B', 'BIOCHEMISTRY', 'assignments', null, null, 'Description of positions', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Positions designated with this AOC include Section, Branch, Division, Department Chiefs, or Director at clinical, forensic and medical research laboratories where the specialty of analytical chemistry, biochemistry, organic chemistry, physiology, toxicology, research pharmacology, or environmental chemistry is required. Officers should also seek out broadening assignment opportunities in a Security Forces Assistance Brigade (SFAB).', 'a0ad3f291c9d6d0b9365ec2e103cf4a9aca7aa72e90c228694813113ec249dd0', 34, 34, '34', 51, null, null, false, null),
  ('d522bfff-8c53-515a-802e-b1098ddf2fb4', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '71B', 'BIOCHEMISTRY', 'prerequisites', null, null, 'Qualifications', 'Medical Service Corps (DA PAM 600-4 chapter)', 'To function as a biochemist or toxicologist minimally requires a master’s degree with specialization in biochemistry or another chemistry specialty (obtainment of a PhD in biochemistry or another chemistry specialty is strongly encouraged to advance through the field grade ranks.). To function as a physiologist requires a PhD in human physiology or in a biological science specialty. Degrees must have been obtained from an accredited program acceptable to TSG.
4. Licensure/certification requirements. The American Board of Clinical Chemistry and the National Registry in Clinical Chemistry are recommended, but not required.', '29901a22057b3fd47361d1c1417045ca4bc6c80e44fd2b22737bc687addd7bd6', 34, 34, '34', 52, null, null, false, null),
  ('38ec0908-df5f-5ac1-b8b7-c94da91b7289', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '71B', 'BIOCHEMISTRY', 'training', null, null, 'Unique education/training opportunities', 'Medical Service Corps (DA PAM 600-4 chapter)', 'The PhD programs in areas such as biochemistry, pharmacology, medicinal chemistry, molecular biology, toxicology, analytical chemistry, and clinical chemistry; Annual Medical Laboratory Sciences (Tri–Service) Short Course. Short courses and conferences include those held by the American Association for Clinical Chemistry, American Society for Clinical Pathology, American Chemical Society, and the Federation of American Societies for Experimental Biology. Another strategic training opportunity includes Program Management Acquisition Internships (PMAIP), with opportunities identified in Long Term Health Education and Training (LTHET) MILPER messages.', 'a313b1f431aaa9d01acc6e4d13f48d26220aa79e5c8e41b67ade471a74c2bf37', 34, 35, '34', 53, null, null, false, null),
  ('307b6c62-0eed-5b42-82db-f57a4bf2975c', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '71E', 'CLINICAL LABORATORY', 'general_duties', null, null, 'Description of duties', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Serves as Section, Branch, Division, Department Chief, or Laboratory Manager responsible for the planning and execution of clinical laboratory testing or medical research and development consistent with unit mission. Supervises testing, provides consultation and expert advice, conducts/directs research, and manages laboratory operations including regulatory requirements, quality systems, fiscal and personnel resources to ensure readiness and standards of care.', 'b62ac6e27877d286c418eb5b6c19f6e64a7aed6efa80a49f08519c32ebeeddf5', 35, 35, '35', 54, null, null, false, null),
  ('ad81ea14-d459-5fe3-9cfa-bff07b273fa1', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '71E', 'CLINICAL LABORATORY', 'assignments', null, null, 'Description of positions', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Positions designated with this AOC include Section, Branch, Division or Department Chiefs, and Laboratory Managers at medical laboratories where broad–based, general laboratory/medical technology, training and experience are required to comply with federal and regulatory requirements. With specialized training such as the Tri-Service Blood Bank Fellowship Program, clinical laboratory officers may serve as Chief of Blood Services, Army Blood Donor Centers, Transfusion Services, or Blood Support Detachment (BSD) Commanders. Positions on unified and Joint staff such as the Joint Blood Program Officer are available for officers interested in plans and operations. Officers should also seek out broadening assignment opportunities in a Security Forces Assistance Brigade (SFAB).', '68cf5207a2eb26763f8a0955be51bb7fb4bef5b010fe43eee6ef418c05c28ad0', 35, 35, '35', 55, null, null, false, null),
  ('3101e0f1-2f04-5d26-951b-9ebe637725d9', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '71E', 'CLINICAL LABORATORY', 'prerequisites', null, null, 'Qualifications', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Requires a bachelor’s degree and certification in Medical Technology/Medical Laboratory Science by a national organization acceptable to TSG.
4. Licensure/certification requirements. Certification in Medical Technology/ Medical Laboratory Science by a national organization acceptable to TSG (e.g. ASCP- American Society for Clinical Pathology).', '09a2c89d24465c2e2931d96b3d4016c47e4b9c937ba28cd38319274316c6bffc', 35, 35, '35', 56, null, null, false, null),
  ('b95211f1-d18f-506f-a4b6-0358944587a5', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '71E', 'CLINICAL LABORATORY', 'training', null, null, 'Unique education/training opportunities', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Various degree and non-degree opportunities are announced annually through MILPER messages such as the LTHET message. Graduate degree opportunities usually include management, informatics, medical technology, and immunohematology disciplines. Non-degree opportunities usually include the TWI Program (e.g. Food & Drug Administration (FDA), American Association of Blood Banks (AABB), Clinical Laboratory Standards Institute (CLSI), etc.). Officers are encouraged to complete at least Program Management Level 1 Defense Acquisition University online training. Officers are strongly encouraged to partake of online or resident training courses (e.g. Defense Acquisition University, Medical Management of Chemical and Biological Casualties (MCBC) or skill badges (Expert Field Medical Badge- EFMB), etc.). Officers are strongly encouraged to become active members in professional organizations (e.g. Society of American Federal Medical Laboratory Scientists (SAFMLS), Clinical Laboratory Management Association (CLMA), AABB, etc.). Another strategic training opportunity includes Program Management Acquisition Internships (PMAIP), with opportunities identified in Long Term Health Education and Training (LTHET) MILPER messages.', 'b2579be4b6e52a5fba911ce0e1420fad088073e546062a588f98b188cc72b34c', 35, 35, '35', 57, null, null, false, null),
  ('a17856b6-04bd-5990-9161-502f450334e2', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '71F', 'RESEARCH PSYCHOLOGY', 'general_duties', null, null, 'Description of duties', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Plans, supervises, and conducts research to determine the effects of physiological, psychological, cognitive, and social variables on the health, readiness, and performance of military personnel; develops research–based programs and products to ameliorate the effects of stressors and enhance health, readiness, and performance.', '80e46f81e799a0ce82b90393ec5cb7304ac1d58c370ddf586ecf131651e88a0c', 36, 36, '36', 58, null, null, false, null),
  ('955dd13a-f204-5b92-a92e-547b11c96c7f', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '71F', 'RESEARCH PSYCHOLOGY', 'assignments', null, null, 'Description of positions', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Positions designated with this AOC include Section, Branch, Division, or Department Chiefs at medical research laboratories where the specialty of neuroscience, human performance research, sleep management research, environmental stressors research, animal models of behavior research, or occupational health and deployment clinical health research is required. Officers also serve in senior staff positions within the AMEDD, TRADOC and HQDA.', '2e0d8d99fc6efef422452c857cb7b96397b20d61935ff6c2554c2ef3c8892f38', 36, 36, '36', 59, null, null, false, null),
  ('86a9f142-c84a-5e26-b24c-e11e91df09e2', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '71F', 'RESEARCH PSYCHOLOGY', 'prerequisites', null, null, 'Qualifications', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Requires a PhD in psychology or related behavioral science with strong research emphasis from an accredited program acceptable to TSG.
4. Licensure/certification requirements. None beyond the doctorate.', 'c81d7b682734e35130898afeeb57c111cee31ace573a16b6374fe40b8b867a51', 36, 36, '36', 60, null, null, false, null),
  ('a683c25b-c623-5197-8ddc-777e560b778d', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '71F', 'RESEARCH PSYCHOLOGY', 'training', null, null, 'Unique education/training opportunities', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Biennial AMEDD Post Graduate Course in Psychology; acquisition training, master’s degree in Research Administration, in addition to the entry–level required Doctorate degree in Psychology. Another strategic training opportunity includes Program Management Acquisition Internships (PMAIP), with opportunities identified in Long Term Health Education and Training (LTHET) MILPER messages.
(4) MFA 71 Skills. Skills enhancing the unique capabilities of MFA 71 include: 5K, Instructor, 7A, Environmental Chemistry; 8T, Blood Banking; 8Z, Medical Research, Development, Test, and Evaluation; 8R, Master Resilience Trainer; 9F, Microbiology; 9G, Immunology; 9H, Parasitology; 9J, Physiology; 9K, Radiobiology; 9L, Toxicology; 9N, Biochemistry; 9P, Pharmacology; 9Q, Psychology (Research and Development Administration); 9A (proficiency level), 8X, Acquisition.', '6692a69a2203764c924a1c89f434535b8b75eb437792f4f0c99227be372b2cf7', 36, 37, '36', 61, null, null, false, null),
  ('ad591bbc-4a6b-568d-9c7f-819b52fba13f', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '72A', 'NUCLEAR MEDICAL SCIENCE', 'general_duties', null, null, 'Description of duties', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Plans, leads, directs, and executes activities relating to health physics (radiation safety) and CBRN medical defense in support of military operations. Functions in medical nuclear/radiological defense operations, nuclear elimination missions, radiation safety programs, staff assignments, and as instructors in these and related fields of public, occupational, and environmental health physics. Provides identification, evaluation, and guidance for personnel protection and for control of potential radiation hazards in TOE/TDA working environments, materiel, munitions, and armament. Serves as health physics subject matter expert on emergency response teams, including Radiological Advisory Medical Teams (RAMT). Provides health physics guidance in the life cycle management of radioactive Army commodities. Provides input to Army and AMEDD policy regarding depleted uranium munitions and armor. Manages Nuclear Regulatory Commission (NRC) licenses in the health care setting, facilitating direct patient care in nuclear medicine, radiation oncology, and other diagnostic and therapeutic modalities.', '0b9b0fb6d424ea0c6b819f410c0ab1f916bfb3f7a8f31118478ba1328c2ab6bb', 37, 37, '37', 62, null, null, false, null),
  ('df99030a-dcea-5ae0-9cda-189459878013', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '72A', 'NUCLEAR MEDICAL SCIENCE', 'assignments', null, null, 'Description of positions', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Positions requiring this AOC include: Radiological Hygiene Consultant, OTSG; Department of Homeland Security Nuclear Detection Specialist; CBRN Medical Defense Staff Officer, Nuclear Disablement Team Member; Pentagon Force Protection Radiological Detection Specialist; Chief, Health Physics; Radiation Safety Officer; Research Investigator; CBRN/Physics/Health Physics Instructor; Commander/OIC/SME Nuclear Medical Science Officer of various TOE/TDA units. Officers should also seek out broadening assignment opportunities in a Security Forces Assistance Brigade (SFAB).', 'd42bcdd3234cc77680d5f7be46922cd1f836345d4de1e4cfeb0bf83fe072a273', 37, 37, '37', 63, null, null, false, null),
  ('3b48b68a-6d5d-5587-963d-4da509625188', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '72A', 'NUCLEAR MEDICAL SCIENCE', 'prerequisites', null, null, 'Qualifications', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Minimum required degree for initial entry into the AOC is a Bachelor of Science degree in Physics (any type), Engineering (any type), Radiobiology, or Chemistry from a school acceptable to TSG; preferred initial entry degrees are health physics, medical physics, and nuclear engineering. Required degree for full AOC qualification is a Master of Science or PhD in Health Physics, Medical Physics, or Nuclear Engineering. For retention at the field grade level, officers should possess full academic AOC qualifications.
4. Licensure/certification requirements. For retention at the field grade level, certification by the American Board of Health Physics (ABHP) or the American Board of Radiology (ABR) is encouraged.', '4b8ff29d3977816b5d7551de4399fd7212f9731b14a7a1fe1f252f0ed14a8c49', 37, 37, '37', 64, null, null, false, null),
  ('21362c29-5b9d-54e0-a673-0f79d22269a2', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '72A', 'NUCLEAR MEDICAL SCIENCE', 'training', null, null, 'Unique education/training opportunities', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Opportunities are available to earn a centrally-funded postgraduate degree (Master of Science or PhD in Health Physics, Medical Physics, or Nuclear Engineering), with subsequent utilization in an appropriate command, staff, or technical application assignment. A limited number of opportunities may be available for the TWI Program, with subsequent utilization tour. Annual and periodic specialty-specific workshops, courses, and conferences are also available, such as the Radiological Hazards Operations Training course and the Medical X-ray Survey Techniques course. Courses conducted at the Defense Nuclear Weapons School are also available, such as the Nuclear Weapons Orientation Course and the Nuclear Weapons Incident Response Training course. Leadership enhancement courses are also available for managing military and civilian personnel and understanding business processes and procedures. Another strategic training opportunity includes Program Management Acquisition Internships (PMAIP), with opportunities identified in Long Term Health Education and Training (LTHET) MILPER messages.', '2ab06a40913c7816879ea90bbfaa59bd1ec164315dd37b69c80d3dc7e9c99c13', 37, 38, '37', 65, null, null, false, null),
  ('27e38604-bcb2-5cf8-b931-9224067d34c2', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '72A', 'NUCLEAR MEDICAL SCIENCE', 'skills', null, null, 'Unique skills', 'Medical Service Corps (DA PAM 600-4 chapter)', 'In addition to the skill sets outlined in figure 1, 72As are expected to develop the following skill sets at the following levels:
a. LT/CPT. Basic–level health physics skills: Radiation health risk assessment; radiation dose calculations (including fetal dose calculations); medical effects of ionizing radiation (MEIR Course) and non-ionizing radiation; diagnostic x–ray room shielding design and verification; area radiation and contamination surveys; radiation instrumentation, detection and measurement (ORAU Applied Health Physics Course); compliance inspections of diagnostic imaging equipment (6H-F18: Medical X-Ray Survey Techniques course); decontamination of people and materiel; radiological response to emergency and CBRN operations (6H-F45, Radiological Hazards Operator Course; 6H-F37: Field Management of Chemical and Biological Casualties Course; 6I-F10: Hospital Management of Chemical, Biological, Radiological, Nuclear, and Explosive Incidents Course; ORAU Health Physics in Radiation Emergencies Course); packaging, storage, and disposition of radioactive waste (Radioactive Commodities Identification and Transportation course). Manage radiation safety programs at the unit or MEDDAC level, including limited-scope NRC licenses; decommission radioactive material facilities with limited-scope NRC licenses; obtain or terminate limited-scope NRC licenses. Serve as Laser Safety Officer (6H-F17: Laser and Radiofrequency Radiation Hazards course). Preventive Medicine officer development (6A-F5: Principles of Military Preventive Medicine course). Potential to command at HHC level within a TDA or TOE assignment. Officers of this rank should complete Part 1 of their certification (ABHP or ABR).', '6a711d148de5e35bde239a993428c8539cbdacea5c013259747d6fea3c4e95ac', 38, 38, '38', 66, null, null, false, null),
  ('22f71362-a4ae-5ed2-93d0-18c3ed285f60', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '72A', 'NUCLEAR MEDICAL SCIENCE', 'skills', 'O-4', null, 'Unique skills (MAJ)', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Advanced-level health physics skills. Basic-level health physics skills as above, plus: population radiation health risk assessment and communication (Health Risk Communication Training); linear accelerator and high-activity radiation source shielding design and verification; portable and laboratory–based radiation instrumentation. Manage radiation safety programs at the MEDCEN, Regional, or medical task force level, including broad-scope NRC licenses; decommission radioactive materials facilities with broad-scope NRC licenses; obtain or terminate broad-scope NRC licenses. Team Chief for the RAMT or the Specialized MEDCOM Response Capabilities – Public Health (SMRC-PH) Team. Conduct nuclear elimination missions and provide Operational Exposure Guidance recommendations to tactical commanders. Provide doctrine and technical input to nuclear/radiological policies at the AMEDD level; manage training programs for nuclear elimination missions. Instruct at the MEDCoE, the U.S. Military Academy (USMA), or the U.S. Army CBRN School. Potential for staff leadership opportunities within the Medical Treatment Facilities to include Chief, Preventive Medicine Service. Officers of this rank should complete their certification (ABHP or ABR).', '79b3848dcc8bd2436c7fd9e68181e5a99d2e674e711ed6df28350b29d50b473c', 38, 38, '38', 67, null, null, false, null),
  ('37be093a-2446-5d48-b0d3-566b93bc9403', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '72A', 'NUCLEAR MEDICAL SCIENCE', 'skills', 'O-5', null, 'Unique skills (LTC)', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Program–level health physics skills. Advanced health physics skills as above, plus: Conduct Joint radiological operations in a deployed environment. Perform or support radiation research. Manage training programs at the MEDCoE and the U.S. Army CBRN School. Manage radiation safety programs at the major subordinate command or deployed MEDCOM level. Potential for Senior Executive Leadership positions and command opportunities internal to MEDCOM.', 'd93bfac7e0d5d5d7309d2f5cc001ac045cb9886196c80cd7efdf4443e7a88a0b', 38, 38, '38', 68, null, null, false, null),
  ('9e76ed9d-be6d-52f0-9a88-32c06cea1519', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '72A', 'NUCLEAR MEDICAL SCIENCE', 'skills', 'O-6', null, 'Unique skills (COL)', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Consultative health physics skills. Provide health physics consultation at the OTSG and Army level. Author Army policy for control of radiation and radioactive material. Conduct Joint and interagency planning for radiological/nuclear emergencies. Oversee AMEDD health physics capabilities for response to a radiological attack or other radiation emergency. Provide technical oversight to Army reactor operations, the Army Radiation Safety Program, and the depleted uranium post–exposure program. Coordinate on health physics issues with other Services and government agencies. Manage radiation safety programs at the DRU, ACOM, ASCC or theater level. Potential for 05A immaterial MEDCOM Senior Executive Leadership positions and command.', '6ce3b9ccf4a777c138a54260cb5c391fcd01b96451a273952e48d11974f14cb7', 38, 38, '38', 69, null, null, false, null),
  ('771ec2b6-5805-530c-ad2f-100daa7c842d', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '72B', 'ENTOMOLOGY', 'general_duties', null, null, 'Description of duties', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Plans, leads, manages, advises, directs, and participates in operational, consultative, training, product development and research in medical entomology to ensure effective control of pests and vectors of disease affecting the health, morale, and environment of all Army personnel. Also serves in command and staff assignments throughout the DoD and Army to ensure property and materiel are not damaged by invertebrate and vertebrate pests.', 'a8830853686709d44caa2791ce7b54e296b705e5750906dccbb555951aaaaef3', 38, 38, '38', 70, null, null, false, null),
  ('e9a94b83-a98d-5d78-a1c6-adbf55e41b74', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '72B', 'ENTOMOLOGY', 'assignments', null, null, 'Description of positions', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Officers in this AOC will fill positions including, but not limited to, the following: Director, Deputy Director, Contingency Liaison Officer, or Research Liaison Officer at the Armed Forces Pest Management Board; DRU, ACOM, ASCC entomologist for Defense Logistics Agency; Commander or Executive Officer of a TOE detachment; Division Chief or staff officer for DCSOPs, Army Public Health Center (APHC); Entomology Staff Officer in a TOE medical brigade or command; Commander, Entomology Division Chief, or staff officer of a APHC subordinate command; Entomology Branch Chief or instructor at the Medical Center of Excellence; Branch Chief or entomologist in the Preventive Medicine Service of a MEDDAC or MEDCEN; Chief, Department of Entomology or Research Investigator at either the Walter Reed Army Institute of Research, one of its subordinate commands, or the U.S. Army Medical Research Institute of Infectious Disease. Officers should also seek out broadening assignment opportunities in a Security Forces Assistance Brigade (SFAB).', 'cbbb3e10c092f88372e93c1a18ff7237c75e59b5ab8bb0493e541104b5acc499', 38, 39, '38', 71, null, null, false, null),
  ('27941ec4-0bee-56b6-ba2e-5577d196d343', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '72B', 'ENTOMOLOGY', 'prerequisites', null, null, 'Qualifications', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Requires a master’s or doctoral degree from an accredited program acceptable to TSG in medical entomology. Additional considerations include Master of Science or PhD degrees from accredited programs acceptable to TSG in related biological disciplines with significant medical entomology courses and laboratory work, extensive professional entomological experience in combination with a graduate degree from an accredited program acceptable to TSG, or Bachelor of Science degree in Entomology from an accredited program acceptable to TSG, combined with an appropriate medical entomology course work and/or applicable professional experience.
4. Licensure certification requirements. For retention at all grades, 72B officers must maintain current DoD Pest Management Certification and Re–certification at required intervals via approved DoD courses (6H–F12, 13). Designation as a Board Certified Entomologist (BCE) in the category of Medical and Veterinary Entomology can be attained through the Entomological Society of America. The Entomological Society of America provides designation as a Board Certified Entomologist (BCE) in the category of Medical and Veterinary Entomology through a nationally recognized program. Upon successful completion, 72B officers may add the BCE as an official entry on their ORB.', 'dcf18b702e30a60ecda11b7e8786127728bd967566cae499f67985ed188ec997', 39, 39, '39', 72, null, null, false, null),
  ('b9cb8dc2-3dd7-5203-85bf-a9f026bf5e5d', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '72B', 'ENTOMOLOGY', 'training', null, null, 'Unique education/training opportunities', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Principles of Military Preventive Medicine (6A–F5), DoD Pest Management Certification and Re–certification Courses (6H–F12, 13) taught at the AMEDD Center & School; DoD Pest Management Workshops sponsored by the Armed Forces Pest Management Board; USAF Aerial Application of Pesticides Certification Course; USN Operational Entomology Course. Annual and periodic specialty–specific workshops, courses, and conferences are also available to military entomologists. A limited number of opportunities to return to graduate school to earn a M.S. or PhD in entomology, or to participate in a TWI Program experience are available through a competitive, board selection process. Another strategic training opportunity includes Program Management Acquisition Internships (PMAIP), with opportunities identified in Long Term Health Education and Training (LTHET) MILPER messages.', 'be08f1e806f63aaf9bcca7d305f5a4992b236cc2eb9eb6298f1c645f81ebd5c6', 39, 39, '39', 73, null, null, false, null),
  ('41971cc1-2730-541b-840a-45e029afb231', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '72B', 'ENTOMOLOGY', 'skills', null, null, 'Unique skills', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Besides the skill sets outlined in figure 1, 72Bs are expected to have developed the following skill sets at the following levels:
a. LT/CPT. DoD Pest Management Certification.', '58d0775b18cbce16a58a746baa13514e99c7c993223f0a7aac41a256248777d1', 39, 39, '39', 74, null, null, false, null),
  ('870e40e8-5b6e-51e3-a00f-11322297b253', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '72B', 'ENTOMOLOGY', 'skills', 'O-4', null, 'Unique skills (MAJ)', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Board Certification, Entomological Society of America.', '1e59eb5231baeae998c444664b93f518daff17a4f22d0a8bae39ba623c12c6ca', 39, 39, '39', 75, null, null, false, null),
  ('4980d835-8f2d-5b17-997a-738006f2bc40', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '72B', 'ENTOMOLOGY', 'skills', 'O-5', null, 'Unique skills (LTC)', 'Medical Service Corps (DA PAM 600-4 chapter)', '9A Designator in Entomology.', '13f49f64481675b0704de5250475ddc7f7a40dcf75235c0241269aa20df52be9', 39, 39, '39', 76, null, null, false, null),
  ('d6f323cb-f0b6-5ec0-a601-8a464cb96337', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '72B', 'ENTOMOLOGY', 'skills', 'O-6', null, 'Unique skills (COL)', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Committee Chairperson, AFPMB.', '7336fdaac556b5f279fe357dee00d41efae6994ae455ede369e5fa8d017328ea', 39, 39, '39', 77, null, null, false, null),
  ('56df52a9-0bc2-56d5-8d4b-725afa0e04e8', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '72C', 'AUDIOLOGY', 'general_duties', null, null, 'Description of duties', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Provides services in support of the Army Hearing Program (AHP) which includes operational hearing, hearing readiness, clinical hearing, and hearing conservation services for all military personnel and civilian personnel routinely exposed to hazardous noise.
a. Operational Hearing Services: Provides policy guidance on hearing conservation, communicates with medical units on hearing-related issues, monitors and analyzes hearing loss trends of deployed Soldiers, provides consultation and on-site technical assistance to support noise evaluations, provide clinical services in theater, serve as subject matter expert for hearing protection and communication devices.
b. Hearing Readiness Services: Ensures that Soldiers have the required hearing capability to perform their duties. Conducts monitoring audiometry, assigns hearing readiness classification, educates on the effects of noise exposure, and provides hearing protection and appropriate communication devices.
c. Clinical hearing services: Performs audiologic and balance evaluations to quantify auditory injury and to determine auditory fitness for duty, develops and implements audiologic treatment, rehabilitation, and management plan. Determines and assigns hearing profile as appropriate. Provides training and counseling regarding hearing health.
d. Hearing conservation services: Manages comprehensive programs for all noise-exposed personnel. Program components are: noise hazard identification, engineering controls, hearing protectors, monitoring audiometry, health education, program enforcement, and program evaluation. Serves as a Course Director, Council for Accreditation of Occupational Hearing Conservationists (CAOHC) to train and certify technicians.', '5edd798d96c10dff9f593edaa84a4cb402293a51907af58c608b7364dc111287', 39, 40, '39', 78, null, null, false, null),
  ('fa155eae-512b-5cee-a146-d659f811b1aa', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '72C', 'AUDIOLOGY', 'assignments', null, null, 'Description of positions', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Positions requiring this AOC include: Chief/Director, Audiology/Hearing Program, MEDDAC; Instructor, AMEDD C&S/METC; Chief/Director, Audiology/ Hearing Program MEDCEN; Director, Acoustics Research; Hearing Program Staff Officer, USAPHC; Staff Officer, Public Health Directorate, OTSG; RHC Audiology/Hearing Program Consultant, and Audiology/Hearing Program Consultant to TSG. Officers should also seek out broadening assignment opportunities in a Security Forces Assistance Brigade (SFAB).', '0b4463f60e0d1793a69138202298190fcd9e43f1dc062789b5d8586e89a387ad', 40, 40, '40', 79, null, null, false, null),
  ('c12d13c4-4364-5e6b-bcda-b7e70387da47', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '72C', 'AUDIOLOGY', 'prerequisites', null, null, 'Qualifications', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Requires a doctoral degree from an educational program accredited by the American Speech-Language Hearing Association’s (ASHA) Council on Academic Accreditation in Audiology and Speech Pathology (CAA) or the Council on Higher Education Accreditation (CHEA). Candidates with a clinical doctoral degree (Au. D) must have completed an accredited one-year clinical audiology externship or be enrolled in the Army Audiology Externship Program (AEP). Professional qualifications for unrestricted practice must be met.
4. Licensure/certification requirements. Must have a license to practice audiology in the United States. Certificate of Clinical Competence awarded by the American Speech–Language–Hearing Association or the Audiology Board Certification (ABA) awarded by the American Academy of Audiology (AAA) is required prior to entrance on active duty for fully qualified candidates. For AEP candidates, certification must be obtained upon completion of the externship year. Certification as a CAOHC course director is required within 2 years of entry to active duty.', '898f2934b6649e929a2fc4c7361c2e735381c4b23d9d4a5cb601251e227b630c', 40, 40, '40', 80, null, null, false, null),
  ('248cf582-b5dc-5e26-bbb1-39a8e742b265', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '72C', 'AUDIOLOGY', 'training', null, null, 'Unique education/training opportunities', 'Medical Service Corps (DA PAM 600-4 chapter)', 'A limited number of opportunities are available to earn a centrally-funded postgraduate advanced degree (PhD and master''s degree level), with subsequent utilization in an appropriate staff or technical application assignment. Annual and periodic specialty- specific workshops, courses, and conferences are also available. A doctoral degree in audiology is the standard entry-level degree for officers in this AOC, although master''s degree level audiologists may be granted an exception to this guideline, dependent upon their professional experience. Another strategic training opportunity includes Program Management Acquisition Internships (PMAIP), with opportunities identified in Long Term Health Education and Training (LTHET) MILPER messages.', '5e2bd4f18bf052651fbbd19aebc64fa469899206e77aa864ed5b2da37a81f3b3', 40, 40, '40', 81, null, null, false, null),
  ('661fb13a-fda1-5d36-9820-689e0bbe979a', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '72D', 'ENVIRONMENTAL SCIENCE AND ENGINEERING', 'general_duties', null, null, 'Description of duties (the chapter titles this AOC "Environmental Science & Engineer Officer")', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Advises on or performs professional and scientific work in environmental health, public health, industrial hygiene, vector ecology, and environmental engineering. Functions include: identification, evaluation, and formulation of recommendations for the control of potential health hazards; health hazard assessment of weapons, equipment, clothing, training, and materiel systems; development of environmental health and industrial hygiene criteria and standards; promotion of policies, programs, practices, and operations directed toward the prevention of disease, illness, overall morbidity and injury; and design and formulations of recommendations to preserve and enhance health and environmental conditions to include air, water, food sanitation waste water, noise, solid and hazardous waste treatment and management, and institutional hygiene. Duties are performed in TOE/TDA organizations, both CONUS and OCONUS.', '9e2f1d89d6631bcc69df25aa62142cd7adcab17c60c38e2375da1e1738a84148', 41, 42, '41', 82, null, null, false, null),
  ('12863a75-85d0-5aa7-a2a0-ca542fd0b46a', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '72D', 'ENVIRONMENTAL SCIENCE AND ENGINEERING', 'assignments', null, null, 'Description of positions', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Positions requiring this AOC include: Commander, TOE Preventive Medicine Detachments, various TDA Activities and Agencies; Executive Officer and Environmental Sciences Officer, various TOE Units; Assistant, Occupational Health, Army and DoD Secretariat; Environmental Science and Engineering Staff Officer, OTSG and various COCOMs; Action Officer for the Joint Chiefs of Staff and The Assistant Secretary of Defense (Health Affairs); Program Manager, Industrial Hygiene Field Services, Army Institute of Public Health, USAPCS; Division and Department Chief, USAPHS Region; Project Officer, various Research, Development, Test, and Evaluation organizations; Chief, Environmental Health Section, various MEDDACs and MEDCENs; Instructor, Environmental Health Branch, MEDCoE; faculty U.S. Military Academy (USMA) or Uniformed Services University of the Health Sciences (USUHS); Assistant Professor, USMA and USUHS; and capability developer, MEDCoE. Officers should also seek out broadening assignment opportunities in a Security Forces Assistance Brigade (SFAB).', 'b9924a0584f2bd441e8ac86bd66c38dc179789348960e4126b3e2c9e5e1ebdc5', 42, 42, '42', 83, null, null, false, null),
  ('8112c574-f994-52f7-9d33-8d11e9486eed', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '72D', 'ENVIRONMENTAL SCIENCE AND ENGINEERING', 'prerequisites', null, null, 'Qualifications', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Must have completed, at a minimum, a bachelor’s degree from an educational program accredited by the Council on Education for Public Health (CEPH) or an agency acceptable to TSG with a major in a public health-relevant field. Preferred majors include public health, environmental health, industrial hygiene, environmental science, epidemiology, and safety management. Degrees with 45 semester hours of mathematics, physics, chemistry, biology and/or physical sciences may also be considered. Alternately, to hold the N4 skill identifier, a bachelor’s degree from a program accredited by the Accreditation Board for Engineering and Technology (ABET), with a major in an environmental engineering-relevant filed, is also acceptable. Preferred majors include environmental engineering, civil engineering, chemical engineering, and mechanical engineering. Waiver requests to the bachelor’s degree requirements will be reviewed and adjudicated by the Environmental Science and Engineering Consultant to TSG. Must be academically qualified for graduate work.
4. Licensure/certification requirements. Obtaining professional state or national registration or certification in a specialty area prior to the field grade level is strongly encouraged. Acceptable licenses/certifications are registration as a Registered Sanitarian or Environmental Health Specialist (RS/REHS) by a State Registration Board or the National Environmental Health Association; licensure as a Professional Engineer (PE) from a State Board in coordination with the National Council of Engineering Examiners; Certification in Public Health (CPH) by the National Board of Public Health Examiners; certification as a Diplomat by the American Academy of Sanitarians (DAAS); certification as a Certified Industrial Hygienist (CIH) by the American Board of Industrial Hygiene; certification as a Safety Professional (CSP) by the Board of Certified Safety Professionals; Board Certified Environmental Engineer (BCEE) by the American Academy of Environmental Engineers and other professional certification acceptable by the Environmental Science and Engineering Consultant to TSG.', '6fe33efc9dc6461732e948d21e373dd547f387abec4f3647ce21ed9004fe1391', 42, 42, '42', 84, null, null, false, null),
  ('4b4de684-e9c8-5a77-8a24-eedb773290e0', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '72D', 'ENVIRONMENTAL SCIENCE AND ENGINEERING', 'training', null, null, 'Unique education/training opportunities', 'Medical Service Corps (DA PAM 600-4 chapter)', 'A limited number of opportunities are available for achievement of a centrally–funded postgraduate advanced degree (PhD and master’s degree level), with subsequent utilization in an appropriate command, staff or technical application assignment. Annual and periodic specialty–specific workshops, courses, and conferences are also available. Recommended graduate degrees include public health, environmental health, industrial hygiene, environmental science, environmental engineering, and other degree concentrations acceptable to TSG. Another strategic training opportunity includes Program Management Acquisition Internships (PMAIP), with opportunities identified in Long Term Health Education and Training (LTHET) MILPER messages.', '366ea744c91e00f9bcc876b0e4fdca0d8d6a72b6d0925342186300d15034e489', 42, 42, '42', 85, null, null, false, null),
  ('5801df1d-6eeb-55cd-9a9b-a16776b42654', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '73A', 'SOCIAL WORK', 'general_duties', null, null, 'Description of duties', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Performs social work functions which include providing direct services, clinical counseling, crisis intervention, disaster relief, traumatic event management, teaching and training, supervision, research, administration, consultation, and policy development in various military settings. These functions are provided to enhance unit readiness and the emotional well–being of military members, their eligible Family members, and DA civilians as appropriate. Duties are performed in CONUS and OCONUS MTOE and TDA organizations.', 'bbad831f2dddc16a8f9fd3407a9972bc360a6574dac8f4c51ff3d03d7b549f2b', 45, 45, '45', 86, null, null, false, null),
  ('9a7830f8-05ce-5f07-8059-e68c8e19f688', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '73A', 'SOCIAL WORK', 'assignments', null, null, 'Description of positions', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Positions includes: Social Work Officer; Behavioral Health Science Officer in a TOE Brigade (Brigade Combat Team, Combat Aviation Brigade, Sustainment Brigade, Special Forces Group, etc.); MTF Social Work Internship Program Director; Corrections Social Work Officer; Instructor at MEDCoE; Chief, Department of Behavioral Health (DBH); Team leader, Embedded Behavioral Health (EBH) Team; Chief, Tele-behavioral Health (TBH); Chief, Addictions Medicine Intensive Outpatient Program (AMIOP); Chief, Intensive Outpatient Program (IOP); Chief, Multi- Disciplinary Outpatient (Multi-D) clinic; Chief, Child and Family Behavioral Health Services (CAFBHS); Director, Family Advocacy Program, U.S. Army Community and Family Support Center; Chief, Behavioral Health Division, MEDCOM; Director, Behavioral Health, United States Disciplinary Barracks; and Social Work Consultant to TSG of the Army. Officers should also seek out broadening assignment opportunities in a Security Forces Assistance Brigade (SFAB).', '84cba10ca8218cb51b8f40e16bbb81258260e05e708d5ad1284bbb24ff3960b7', 45, 45, '45', 87, null, null, false, null),
  ('468e5508-c6cb-557c-9a8e-68eba28902f5', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '73A', 'SOCIAL WORK', 'prerequisites', null, null, 'Qualifications', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Requires a master’s degree in Social Work from a program accredited by the Council on Social Work Education and an independent license which must be acceptable to TSG (i.e. LCSW) and meeting requirements of AR 40-68. All professional qualifications for unrestricted practice must be met.
4. Licensure/certification requirements. All military social workers are required to be licensed. Continuing Education units in accordance with individual’s license are required.', '94b1209b3ab5e106d7a2ea55a2ff76757af92422fbbaec0b3346de44b640ae5f', 45, 45, '45', 88, null, null, false, null),
  ('98cb0608-5140-555f-a9fb-b29128e954e3', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '73A', 'SOCIAL WORK', 'training', null, null, 'Unique education/training opportunities', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Family Advocacy Staff Training Course; Family Advocacy Staff Training Advanced Course; LTHET for a doctoral degree in social work; LTHET for Baylor Master of Health Administration (MHA)/Master of Business Administration (MBA); social work fellowship in Child and Family Practice, evidence-based PTSD treatment courses, traumatic event management and substance use disorder training. Another strategic training opportunity includes Program Management Acquisition Internships (PMAIP), with opportunities identified in Long Term Health Education and Training (LTHET) MILPER messages.', 'bcf21bc74dd23d7d3bd58b3e2fd1afcd6772d9062e7e00cdccce2197f0aaca27', 45, 46, '45', 89, null, null, false, null),
  ('0f2da1c8-e189-5bc2-975d-7d01299becad', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '73B', 'CLINICAL PSYCHOLOGY', 'general_duties', null, null, 'Description of duties', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Applies psychological principles, theories, methods, and techniques through direct patient services, consultation, education, and research in problems of human effectiveness, adjustment, and emotional disturbance in medical and other settings. Concerned with investigations, evaluations, and amelioration of mental and behavior disorders; prevention of mental illness; promotion of effective mental health.', '1bb988b22b68969c4aae009017f8fd669deebd9e730b3eea2c90d08137ef9d06', 48, 48, '48', 90, null, null, false, null),
  ('6d37175c-e836-5c62-ab5e-4c2ff35d4422', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '73B', 'CLINICAL PSYCHOLOGY', 'assignments', null, null, 'Description of positions', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Positions requiring this AOC include: Clinical Psychology Consultant, OTSG; Clinical Psychology Consultant, DRU, ACOM, ASCC; Chief, Clinical Psychology Service, MEDCEN; Director of Training, Psychology Internship/Fellowship Program; Chief, Clinical Psychology Service, MEDDAC; Staff Psychologist, Clinical Psychology Service; Combat Stress Control Detachment/ Company Psychologist; Division Psychologist; Operational Psychologist. Officers should also seek out broadening assignment opportunities in a Security Forces Assistance Brigade (SFAB).', 'd401ef7fbf48998330628a32152312029b7b23348d5b389afddac62851296e18', 48, 48, '48', 91, null, null, false, null),
  ('37a7cbec-ed0e-5bf1-aa31-43a94864c150', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '73B', 'CLINICAL PSYCHOLOGY', 'prerequisites', null, null, 'Qualifications', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Must possess a PhD or PsyD in clinical psychology or counseling psychology, from an American Psychological Association (APA) accredited program. Must have completed a one year APA accredited clinical psychology internship or its equivalent. Professional qualifications for unrestricted practice must be met.
4. Licensure/certification requirements. Must have a current, valid, and unrestricted license to independently practice psychology in the United States, U.S. Territories, or the District of Columbia. For Clinical Psychology Internship Program (CPIP) graduates, there are two possible licensing pathways. All CPIP graduates will obtain a license within 18 months after completion of all requirements for a doctoral degree. During this time period, these CPIP graduates will not have favorable personnel actions suspended because they are unlicensed. Direct accession clinical psychologists must possess a current, valid, and unrestricted license upon commissioning.', '2f8601d083dc1e1a3453306c98599783abadf0da087702ed59d6c12dd9120f40', 48, 48, '48', 92, null, null, false, null),
  ('909f12c5-6545-5cb2-8d4f-c1798120a36d', '752ba019-b8e9-50a5-99ce-a1c7001c8b28', 'Army', 'officer', '73B', 'CLINICAL PSYCHOLOGY', 'training', null, null, 'Unique education/training opportunities', 'Medical Service Corps (DA PAM 600-4 chapter)', 'Aeromedical Psychology Short Course, Behavioral Science Consultation Team Course and the Combat Casualty Care Course (C4). Postdoctoral fellowships include neuropsychology, child/pediatric psychology, health psychology, forensic psychology, trauma treatment and health care delivery. Another strategic training opportunity includes Program Management Acquisition Internships (PMAIP), with opportunities identified in Long Term Health Education and Training (LTHET) MILPER messages.
7. Skills. Professional level 9A is a skill enhancing the unique capabilities of MFA 73. Instructor qualification 5K, BSCT qualification 8B, SERE Psychologist M6 and Aeromedical Psychologist qualification N7 are also skills which enhance AOC 73B.', '0024e3bf78e318c947c6be45042f19cac38d12b79f9e5dcca01cbfed888933a3', 48, 48, '48', 93, null, null, false, null);
